// Changelog has contents of changelog and how to get it.
// Method: models.detectionMethodStr
type Changelog struct {
	Contents string          `json:"contents"`
	Method   DetectionMethod `json:"method"`
}

// AffectedProcess keep a processes information affected by software update
type AffectedProcess struct {
	PID         string       `json:"pid,omitempty"`
	Name        string       `json:"name,omitempty"`
	ListenPorts []ListenPort `json:"listenPorts,omitempty"`
}

// ListenPort has the result of parsing the port information to the address and port.
type ListenPort struct {
	Address           string   `json:"address"`
	Port              string   `json:"port"`
	PortScanSuccessOn []string `json:"portScanSuccessOn"`
}

// HasPortScanSuccessOn checks if Package.AffectedProcs has PortScanSuccessOn
func (p Package) HasPortScanSuccessOn() bool {
	for _, ap := range p.AffectedProcs {
		for _, lp := range ap.ListenPorts {
			if len(lp.PortScanSuccessOn) > 0 {
				return true
			}
		}
	}

	return false
}

// NeedRestartProcess keep a processes information affected by software update
type NeedRestartProcess struct {
	PID         string `json:"pid"`
	Path        string `json:"path"`
	ServiceName string `json:"serviceName"`
	InitSystem  string `json:"initSystem"`
	HasInit     bool   `json:"-"`
}

// SrcPackage has installed source package information.
// Debian based Linux has both of package and source information in dpkg.
// OVAL database often includes a source version (Not a binary version),
// so it is also needed to capture source version for OVAL version comparison.
// https://github.com/future-architect/vuls/issues/504
type SrcPackage struct {
	Name        string   `json:"name"`
	Version     string   `json:"version"`
	Arch        string   `json:"arch"`
	BinaryNames []string `json:"binaryNames"`
